{
  "aic": "",
  "active": false,
  "lastModifiedTime": "2026-10-17T11:31:49+08:00",
  "protocolVersion": "02.02",
  "name": "任务协调智能体",
  "description": "创建协作任务和群组，邀请消息回声智能体参与，发送任务并汇总执行记录。通过消息收件箱接收邀请和任务，回传原消息、身份和任务状态。",
  "version": "0.1.0",
  "provider": {
    "name": "匿名提供者"
  },
  "securitySchemes": {
    "mtls": {
      "type": "mutualTLS",
      "description": "使用 AIC clientAuth 证书建立 AMQPS 连接，接收 Inbox 邀请并访问群组授权服务。"
    }
  },
  "endPoints": [
    {
      "url": "amqps://wt.ioa.pub:5671/acps?inbox=inbox_{AIC}",
      "transport": "AMQP",
      "security": [
        {
          "mtls": []
        }
      ]
    }
  ],
  "capabilities": {
    "streaming": false,
    "notification": false,
    "messageQueue": [
      "amqp:0.9.1"
    ]
  },
  "defaultInputModes": [
    "application/json",
    "text/plain"
  ],
  "defaultOutputModes": [
    "application/json"
  ],
  "skills": [
    {
      "id": "interop.probe.coordinate",
      "name": "消息任务编排",
      "description": "生成随机消息，发起 read-only-probe 任务，汇总回传消息、智能体身份和执行状态，发送任务完成指令。",
      "version": "0.1.0",
      "tags": [
        "任务协调",
        "消息协作",
        "AIP"
      ],
      "inputModes": [
        "application/json",
        "text/plain"
      ],
      "outputModes": [
        "application/json"
      ]
    },
    {
      "id": "interop.message.receive",
      "name": "消息接收与回传",
      "description": "接收 operation 为 read-only-probe 的 JSON 任务，读取 nonce，返回 nonce、partner_aic、observed_utc、result 和 business_mutations，并更新任务状态。",
      "version": "0.1.0",
      "tags": [
        "消息接收",
        "消息回传",
        "AMQPS Inbox",
        "AIP"
      ],
      "examples": [
        "{\"operation\":\"read-only-probe\",\"nonce\":\"hello-001\"}"
      ],
      "inputModes": [
        "application/json",
        "text/plain"
      ],
      "outputModes": [
        "application/json"
      ]
    }
  ]
}
